import {groupFixture} from './project-reactions';import type {Condition} from '../../src/domain/contracts';
export function term(key:string,basis:string,terms:string[],complete=true):Condition{return {key,dimension:'composition',basis,unit:'',value_state:'reported',kind:'composition',lower:null,upper:null,lower_inclusive:true,upper_inclusive:true,terms,inventory_complete:complete,raw_value_text:'SYNTHETIC '+terms.join(', '),raw_unit:'',derivation:'reported',calculation:null};}
export function whiteboardFixture(){const d=groupFixture();for(const v of d.versions){v.payload.compounds[0].name='SYNTHETIC glucose';v.payload.experiment.conditions.push(term('substrate','feed',['glucose']),term('alkali','added_alkali',['NaOH']),term('solvent','reaction_medium',['water']),term('atmosphere','headspace',['inert']),term('added_catalyst','added_catalyst',['none']),{...v.payload.experiment.conditions[0],key:'NaOH_concentration',dimension:'concentration',basis:'solution_volume',unit:'mol/L',lower:1,upper:2,raw_value_text:'SYNTHETIC 1–2 mol/L'});}
 d.identities[0].label='SYNTHETIC free glucose';d.identities[0].definition=structuredClone(d.versions[0].payload);
 function copy(index:number,suffix:string){const v=structuredClone(d.versions[index]);v.id=suffix;v.case_id=suffix+'-case';v.payload.experiment.original_experiment_id=suffix+'-original';v.payload.experiment.independence_group_id=suffix+'-independent';d.versions.push(v);d.mappings.push({...d.mappings[index],id:suffix+'-mapping',case_version_id:v.id});d.reviews.push({...d.reviews[index],id:suffix+'-review',case_version_id:v.id});return v;}
 const refute=copy(0,'refutation');refute.payload.evidence.stance='refutes';
 const cellulose=copy(0,'cellulose');cellulose.payload.compounds[0].node_type='polymer';cellulose.payload.compounds[0].structure_context='bound';cellulose.payload.experiment.conditions.find(c=>c.key==='substrate')!.terms=['cellulose'];d.identities.push({...d.identities[0],id:'cellulose-identity',label:'SYNTHETIC cellulose (same display name)',definition:structuredClone(cellulose.payload)});d.mappings.at(-1)!.identity_id='cellulose-identity';
 const oxygen=copy(0,'oxygen');oxygen.payload.experiment.conditions.find(c=>c.key==='atmosphere')!.terms=['air'];oxygen.payload.experiment.conditions.find(c=>c.key==='added_catalyst')!.terms=['SYNTHETIC Ni'];oxygen.payload.experiment.conditions.find(c=>c.key==='substrate')!.terms=['glucose','cellulose'];
 for(const a of d.anchors)Object.assign(a,{physical_page_start:2,physical_page_end:3,printed_page_label:'SYNTHETIC ii',verbatim_passage:'SYNTHETIC source passage. Fabricated test only.'});return d;}
